INSERT INTO sections (id, type, name, sort_order, is_visible, content) VALUES
(1, 'hero', 'الواجهة الرئيسية (Hero)', 1, 1, '{"anchor":"donate","eyebrow":{"ar":"مؤسسة عيد الخيرية — قطر","en":"Eid Charity — Qatar"},"title":{"ar":"عطاؤك","en":"Your Gift"},"title_gold":{"ar":"يصنع أثرًا","en":"Makes an Impact"},"subtitle":{"ar":"من قطر، نصل بعطائكم إلى الإنسان ونصنع أثرًا مستدامًا في حياة المجتمعات.","en":"From Qatar, your generosity reaches people in need, creating lasting and sustainable impact in communities worldwide."},"btn_primary":{"ar":"تبرع الآن","en":"Donate Now"},"btn_primary_url":"#donate","btn_secondary":{"ar":"اكتشف أثرنا","en":"Discover Our Impact"},"btn_secondary_url":"#impact","show_donation_card":true,"donate_title":{"ar":"تبرع بسهولة","en":"Donate Easily"},"once_label":{"ar":"مرة واحدة","en":"One Time"},"monthly_label":{"ar":"شهري","en":"Monthly"},"category_placeholder":{"ar":"اختر باب الخير","en":"Choose a category"},"categories":{"ar":"الزكاة\\nالصدقات\\nكفالة الأيتام\\nعلاج المرضى\\nإطعام الطعام\\nسقيا الماء\\nالوقف\\nالمشاريع الخيرية","en":"Zakat\\nSadaqa\\nOrphan Care\\nMedical Aid\\nFood Aid\\nClean Water\\nEndowment\\nCharitable Projects"},"amounts":"100, 300, 500, 1000","default_amount":300,"currency":"QAR","other_amount":{"ar":"مبلغ آخر","en":"Other Amount"},"donate_button":{"ar":"تبرع الآن","en":"Donate Now"},"donate_action_url":"","secure_note":{"ar":"دفع آمن — مرخص من وزارة التنمية الاجتماعية والأسرة","en":"Secure payment — Licensed by Ministry of Social Development & Family"},"slide_seconds":8}'),
(2, 'gates', 'أبواب الخير', 2, 1, '{"anchor":"giving","bg":"white","eyebrow":{"ar":"فرص التبرع","en":"Giving Opportunities"},"title":{"ar":"أبواب الخير","en":"Gates of Goodness"},"subtitle":{"ar":"اختر المجال الأقرب إلى قلبك وساهم في صناعة الأثر.","en":"Choose the cause closest to your heart and help create real impact."},"button":{"ar":"استعرض جميع فرص التبرع","en":"Browse All Giving Opportunities"},"button_url":"#"}'),
(3, 'campaigns', 'الحملات العاجلة', 3, 1, '{"anchor":"campaigns","bg":"warm","eyebrow":{"ar":"الحملات العاجلة","en":"Urgent Campaigns"},"title":{"ar":"حملات تحتاج دعمك الآن","en":"Campaigns That Need Your Support"},"subtitle":{"ar":"مساهمتك اليوم قد تصنع فرقًا حقيقيًا في حياة إنسان.","en":"Your contribution today can make a real difference in someone\'s life."},"button":{"ar":"جميع الحملات","en":"All Campaigns"},"button_url":"#","pct_label":{"ar":"مكتمل","en":"Complete"},"target_label":{"ar":"الهدف","en":"Target"},"raised_label":{"ar":"جُمع","en":"Raised"},"beneficiaries_label":{"ar":"المستفيدون","en":"Beneficiaries"},"cta":{"ar":"ساهم الآن","en":"Contribute Now"},"currency":"QAR"}'),
(4, 'centers', 'مراكز عيد', 4, 1, '{"anchor":"centers","bg":"white","eyebrow":{"ar":"منظومة عيد","en":"Eid Network"},"title":{"ar":"منظومة عيد لخدمة المجتمع","en":"Eid Centers for Community Service"},"subtitle":{"ar":"أربعة مراكز متخصصة تجمعها رسالة واحدة: خدمة الإنسان وبناء المجتمع.","en":"Four specialized centers united by one mission: serving people and building community."},"button":{"ar":"اكتشف المركز","en":"Discover Center"}}'),
(5, 'impact', 'أثر عطائكم (أرقام)', 5, 1, '{"anchor":"impact","eyebrow":{"ar":"في أرقام","en":"In Numbers"},"title":{"ar":"أثر عطائكم","en":"Your Impact"},"subtitle":{"ar":"أرقام تحكي أثرًا صنعه عطاء أهل الخير.","en":"Numbers that tell a story of generosity and real change."},"note":{"ar":"وفق أحدث البيانات المعتمدة — ستُحدَّث الأرقام بالأرقام الرسمية الموثقة","en":"Based on latest verified data — figures will be updated with official statistics"}}'),
(6, 'story', 'قصة أثر', 6, 1, '{"anchor":"story","bg":"cream","image":"https://images.unsplash.com/photo-1488521787991-ed7bbaae773c?w=900&h=780&fit=crop&auto=format&crop=faces","badge":{"ar":"قصة أثر","en":"Impact Story"},"location":{"ar":"من اليمن — 2024","en":"From Yemen — 2024"},"title":{"ar":"حين يتحول العطاء\\nإلى بداية جديدة","en":"When Giving Becomes\\na New Beginning"},"quote":{"ar":"\\"لم أتخيل يومًا أن يصل إلينا من هذه المسافة. كفالة يتيم واحدة غيّرت مسار حياتي وفتحت أمامي أبواب العلم والمستقبل.\\"","en":"\\"I never imagined it could reach us from so far. A single orphan sponsorship changed the course of my life and opened the doors of education and a better future.\\""},"attribution":{"ar":"— أحمد، مستفيد من برنامج كفالة الأيتام، اليمن","en":"— Ahmed, beneficiary of the Orphan Sponsorship Program, Yemen"},"button":{"ar":"اقرأ القصة","en":"Read the Story"},"button_url":"#"}'),
(7, 'projects', 'مشاريعنا', 7, 1, '{"anchor":"projects","bg":"white","eyebrow":{"ar":"على أرض الواقع","en":"On the Ground"},"title":{"ar":"مشاريعنا","en":"Our Projects"},"tab1":{"ar":"داخل قطر","en":"In Qatar"},"tab2":{"ar":"حول العالم","en":"Worldwide"},"view_label":{"ar":"اطلع على المشروع","en":"View Project"}}'),
(8, 'governance', 'الحوكمة والمساءلة', 8, 1, '{"anchor":"governance","eyebrow":{"ar":"الحوكمة والمساءلة","en":"Governance & Accountability"},"title":{"ar":"عطاؤكم أمانة","en":"Your Trust, Our Responsibility"},"subtitle":{"ar":"نلتزم بأعلى معايير الحوكمة والشفافية والمساءلة للحفاظ على ثقة المتبرعين وتعظيم أثر عطائهم.","en":"We uphold the highest standards of governance, transparency, and accountability to honor donor trust and maximize the impact of every gift."},"button":{"ar":"تعرف على الحوكمة والشفافية","en":"Learn About Our Governance"},"button_url":"#","view_label":{"ar":"اطلع الآن","en":"View Now"}}'),
(9, 'join', 'كن جزءًا من الأثر', 9, 1, '{"anchor":"join","bg":"warm","eyebrow":{"ar":"انضم إلينا","en":"Join Us"},"title":{"ar":"كن جزءًا من الأثر","en":"Be Part of the Impact"}}'),
(10, 'media', 'آخر الأخبار', 10, 1, '{"anchor":"media","bg":"white","eyebrow":{"ar":"أخبار وتقارير","en":"News & Reports"},"title":{"ar":"آخر أخبار عيد","en":"Latest Eid News"},"button":{"ar":"زيارة المركز الإعلامي","en":"Visit Media Center"},"button_url":"#"}'),
(11, 'partners', 'شركاء النجاح', 11, 1, '{"anchor":"partners","bg":"warm","eyebrow":{"ar":"معًا نصنع الأثر","en":"Together We Create Impact"},"title":{"ar":"شركاء النجاح","en":"Partners in Success"}}');
